@startuml

class Movie {
  + title : string
}

class Order {
  + order_date : date
}

class User {
  + name : string
}

class Subscriber extends User {
  + card_number : string
  + balance : float
}

User "1" -- "*" Order : places

Subscriber "1" -- "0..1" Movie : hires

Movie "0..*" -- "0..*" Movie : orders

@enduml

